// 弹窗内可见的「切换」按钮（含当前店的禁用按钮）
function modalSwitchButtons() {
  return [...document.querySelectorAll('button,[role=button]')].filter((b) => {
    const t = (b.textContent || '').trim();
    return t === '切换' && visible(b);
  });
}
// 从切店弹窗一行里抠英文店名
function storeNameNear(el) {
  let node = el;
  for (let i = 0; i < 8 && node; i++) {
    const cands = [...node.querySelectorAll('span,div,p,a,button')]
      .map((e) => (e.textContent || '').trim())
      .filter((t) =>
        t.length >= 2 &&
        t.length <= 30 &&
        /^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t) &&
        !isFakeStoreName(t) &&
        !/^(NEW|Beta|Seller|Central)$/i.test(t)
      );
    // 最短优先：避免拿到整行大段文本
    cands.sort((a, b) => a.length - b.length);
    if (cands.length) return cands[0];
    node = node.parentElement;
  }
