1	import { log } from './logger.js';
2	
3	/**
4	 * 通用弹窗关闭策略。登录成功后 / 切换店铺时 / 页面加载后会弹出多种不固定的弹窗，
5	 * 需求明确「一律关闭，可能还会有其他类型的弹窗，都关闭」。已知类型包括：
6	 *   - 推广券 / 调价提效 / 店铺提效 / 新功能提示等营销弹窗
7	 *   - 「您有以下待办任务需要尽快处理」待办任务模态框（右上角 X）
8	 *   - 点击「消息」后弹出的「全部消息」通知面板 / 「商品不合规，影响售卖」通知（右上角 X）
9	 * 策略：多轮「文本按钮 + 关闭图标 + Esc」清扫，不依赖单一选择器。
10	 */
11	
12	// 需要点击的按钮文本（精确/包含匹配）。仅放「关闭/忽略」类，绝不放「去处理/去填写」等会跳转的按钮。
13	const DISMISS_TEXTS = [
14	  '稍后再说', '我知道了', '知道了', '暂不领取', '暂不参与',
15	  '以后再说', '下次再说', '不再提示', '暂不处理', '取消', '关闭',
16	];
17	
18	// 关闭图标的候选选择器（Temu / 常见 UI 库）
19	const CLOSE_ICON_SELECTORS = [
20	  '[aria-label="close"]',
21	  '[aria-label="关闭"]',
22	  '[aria-label="Close"]',
23	  '.ant-modal-close',
24	  '.ant-drawer-close',
25	  '.ant-notification-notice-close',
26	  '[class*="closeIcon"]',
27	  '[class*="close-icon"]',
28	  '[class*="Close_"]',
29	  '[class*="_close"]',
30	  '[class*="closeBtn" i]',
31	  '[class*="close-btn" i]',
32	  'button[class*="close" i]',
33	  'span[class*="close" i]',
34	  'i[class*="close" i]',
35	  'svg[class*="close" i]',
36	  '[class*="icon" i][class*="close" i]',
37	];
38	
39	// 已知弹窗的标题/关键文本。命中后在其容器内优先点关闭图标（这类弹窗没有「关闭」文本按钮，
40	// 只有右上角 X，且往往带「去处理」等会跳转的按钮，绝不能误点）。
41	const KNOWN_DIALOG_KEYWORDS = [
42	  '待办任务需要尽快处理', // 待办任务模态框
43	  '全部消息',             // 消息通知面板
44	  '商品不合规',           // 违规通知
45	];
46	
47	/**
48	 * 关闭当前页面上所有可见弹窗。多轮尝试直到无可关闭项或达到上限。
49	 * @param {import('playwright').Page} page
50	 */
51	export async function closePopups(page, { rounds = 4 } = {}) {
52	  let totalClosed = 0;
53	  for (let r = 0; r < rounds; r++) {
54	    let closedThisRound = 0;
55	
56	    // 1) 文本按钮
57	    for (const t of DISMISS_TEXTS) {
58	      const btn = page.getByRole('button', { name: t, exact: false }).first();
59	      if (await safeClick(btn)) { closedThisRound++; continue; }
60	      const el = page.getByText(t, { exact: true }).first();
61	      if (await safeClick(el)) closedThisRound++;
62	    }
63	
64	    // 2) 已知弹窗：按标题关键字定位其容器，点容器内的关闭图标（避免误点「去处理」等跳转按钮）
65	    for (const kw of KNOWN_DIALOG_KEYWORDS) {
66	      const anchor = page.getByText(kw, { exact: false }).first();
67	      if (!(await anchor.isVisible({ timeout: 300 }).catch(() => false))) continue;
68	      // 容器 class 关键词放宽：除 modal/dialog/drawer/popover 外，
69	      // 「全部消息 / 商品不合规」是自定义通知面板，class 多为 notice/notification/message/panel/popup/card
70	      const container = anchor.locator(
71	        'xpath=ancestor::*[contains(translate(@class,"MDNPCS","mdnpcs"),"modal") or contains(translate(@class,"MDNPCS","mdnpcs"),"dialog") or contains(translate(@class,"MDNPCS","mdnpcs"),"drawer") or contains(translate(@class,"MDNPCS","mdnpcs"),"popover") or contains(translate(@class,"MDNPCS","mdnpcs"),"notice") or contains(translate(@class,"MDNPCS","mdnpcs"),"notification") or contains(translate(@class,"MDNPCS","mdnpcs"),"message") or contains(translate(@class,"MDNPCS","mdnpcs"),"panel") or contains(translate(@class,"MDNPCS","mdnpcs"),"popup") or contains(translate(@class,"MDNPCS","mdnpcs"),"card")][1]'
72	      ).first();
73	      // 依次尝试：命中的语义容器 → 逐级放大的祖先（2/4/6 层），在其中找关闭图标
74	      const scopes = [];
75	      if (await container.count().catch(() => 0)) scopes.push(container);
76	      for (const depth of [2, 4, 6]) scopes.push(anchor.locator(`xpath=ancestor::*[${depth}]`).first());
77	      let done = false;
78	      for (const scope of scopes) {
79	        for (const sel of CLOSE_ICON_SELECTORS) {
80	          const icon = scope.locator(sel).first();
81	          if (await safeClick(icon)) { closedThisRound++; done = true; break; }
82	        }
83	        if (done) break;
84	      }
85	    }
86	
87	    // 3) 关闭图标（全页兜底）
88	    for (const sel of CLOSE_ICON_SELECTORS) {
89	      const icons = page.locator(sel);
90	      const n = Math.min(await icons.count().catch(() => 0), 5);
91	      for (let i = 0; i < n; i++) {
92	        if (await safeClick(icons.nth(i))) closedThisRound++;
93	      }
94	    }
95	
96	    // 4) 兜底 Esc（关闭 modal / drawer）
97	    await page.keyboard.press('Escape').catch(() => {});
98	
99	    totalClosed += closedThisRound;
100	    if (closedThisRound === 0) break;
101	    await page.waitForTimeout(600);
102	  }
103	  if (totalClosed > 0) log.info(`关闭弹窗 ${totalClosed} 个`);
104	  return totalClosed;
105	}
106	
107	async function safeClick(locator) {
108	  try {
109	    if (!(await locator.isVisible({ timeout: 400 }))) return false;
110	    await locator.click({ timeout: 1200, force: true });
111	    return true;
112	  } catch {
113	    return false;
114	  }
115	}
