1	/**
2	 * 会话级切店（右上角头像/店名 → 切换 →「切换店铺」弹窗）
3	 * 对齐 temu-plugin content.js，多 mall 共用账号时必须用此方式，不能用「来源店铺」筛选。
4	 *
5	 * 2026-07-31 加固（同事机「打不开切换店铺弹窗 / 当前=未知」）：
6	 *  - 切店前强制滚回顶，避免顶栏启发式因 scroll 失效
7	 *  - 放宽顶栏店名识别（top 阈值、排除词、假店名过滤）
8	 *  - openStoreModal 多策略：店名 / 箭头 / 头像 / 右上角坐标点
9	 *  - 失败时带回诊断串，方便对照日志
10	 */
11	import { log } from './logger.js';
12	
13	// 注意：经 page.evaluate → eval(helpers) 注入。必须用 function/var，不能用 const/let
14	// （const/let 不泄漏到 evaluate 外层；切店回调里直接调 realClick/sleep/visible 会挂）。
15	const SWITCH_HELPERS = `
16	  function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
17	  function visible(el) {
18	    if (!el) return false;
19	    const r = el.getBoundingClientRect();
20	    return r.width > 0 && r.height > 0;
21	  }
22	  function textEls(re, maxLen) {
23	    maxLen = maxLen == null ? 40 : maxLen;
24	    return [...document.querySelectorAll('*')].filter((e) => {
25	      const t = (e.textContent || '').trim();
26	      return re.test(t) && t.length <= maxLen;
27	    });
28	  }
29	  function clickableAncestor(el) {
30	    let p = el;
31	    for (let i = 0; i < 6 && p; i++, p = p.parentElement) {
32	      if (p.tagName === 'BUTTON' || p.getAttribute('role') === 'button') return p;
33	      // 顶栏店名常包在可点 div 上（cursor:pointer）
34	      try {
35	        const cur = window.getComputedStyle(p).cursor;
36	        if (cur === 'pointer') return p;
37	      } catch (e) {}
38	    }
39	    return el;
40	  }
41	  function realClick(el) {
42	    if (!el) return;
43	    const opts = { bubbles: true, cancelable: true, view: window };
44	    try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
45	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
46	      try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
47	    }
48	    try { el.click(); } catch (e) {}
49	  }
50	  async function waitFor(fn, timeout, step) {
51	    timeout = timeout == null ? 8000 : timeout;
52	    step = step == null ? 300 : step;
53	    const t0 = Date.now();
54	    while (Date.now() - t0 < timeout) {
55	      let v = null;
56	      try { v = fn(); } catch (e) { v = null; }
57	      if (v) return v;
58	      await sleep(step);
59	    }
60	    return null;
61	  }
62	  function innermost(els) {
63	    return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null;
64	  }
65	  // 假店名 / 顶栏噪声（货号、UI 标签、站点名）
66	  function isFakeStoreName(t) {
67	    if (!t) return true;
68	    if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller|Temu|US|EU|Global|CN|UK|DE|FR|All|More)$/i.test(t)) return true;
69	    if (/^[A-Z0-9]{6,}$/.test(t)) return true; // 纯大写货号
70	    if (/^\\d+$/.test(t)) return true;
71	    return false;
72	  }
73	  function findStoreNameEl() {
74	    const W = window.innerWidth || 1280;
75	    let best = null;
76	    // 顶栏常见高度 48–72；headless/缩放后可能略高，放宽到 120
77	    const TOP_MAX = 120;
78	    for (const el of document.querySelectorAll('span,a,div,button,p,b,strong,label')) {
79	      const t = (el.textContent || '').trim();
80	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\\s[A-Za-z0-9]+){0,4}$/.test(t)) continue;
81	      if (t.length < 2 || t.length > 36) continue;
82	      if (isFakeStoreName(t)) continue;
83	      if (el.children.length > 3) continue;
84	      const r = el.getBoundingClientRect();
85	      if (r.width === 0 || r.height === 0) continue;
86	      if (r.top < -4 || r.top > TOP_MAX) continue;
87	      // 右半屏；极窄视口时放宽到 0.35
88	      const leftMin = W < 900 ? W * 0.35 : W * 0.45;
89	      if (r.left < leftMin) continue;
90	      if (!best || r.left > best.left) best = { el, left: r.left, t: t };
91	    }
92	    return best ? best.el : null;
93	  }
94	  function readStoreName() {
95	    const el = findStoreNameEl();
96	    if (!el) return null;
97	    const t = (el.textContent || '').trim();
98	    return isFakeStoreName(t) ? null : t;
99	  }
100	  function modalOpen() {
101	    return textEls(/切换店铺|您的账户存在/, 40).length > 0;
102	  }
103	  function clickTopRightHotspot() {
104	    // 顶栏最右侧一排：头像 / 箭头 / 店名区域，按坐标扫几个点
105	    const W = window.innerWidth || 1280;
106	    const ys = [18, 28, 40, 56];
107	    const xs = [W - 24, W - 48, W - 80, W - 120, W - 160];
108	    for (const y of ys) {
109	      for (const x of xs) {
110	        const el = document.elementFromPoint(x, y);
111	        if (!el) continue;
112	        realClick(clickableAncestor(el));
113	      }
114	    }
115	  }
116	  // 对齐插件：点顶栏店名/箭头 → 下拉「切换」→ 「切换店铺」弹窗
117	  // 返回 {ok, diag[]}
118	  async function openStoreModal() {
119	    const diag = [];
120	    diag.push('W=' + (window.innerWidth || 0) + ' H=' + (window.innerHeight || 0));
121	    // 确保顶栏在视口内
122	    try { window.scrollTo(0, 0); document.documentElement.scrollTop = 0; document.body.scrollTop = 0; } catch (e) {}
123	    await sleep(200);
124	
125	    if (modalOpen()) { diag.push('弹窗已开'); return { ok: true, diag: diag }; }
126	
127	    const nameEl = findStoreNameEl();
128	    diag.push('店名=' + (nameEl ? (nameEl.textContent || '').trim() : 'null'));
129	
130	    // 策略 1：点店名可点祖先 + 右侧箭头
131	    if (nameEl) {
132	      const r = nameEl.getBoundingClientRect();
133	      realClick(clickableAncestor(nameEl));
134	      await sleep(150);
135	      const arrow = document.elementFromPoint(
136	        Math.min((window.innerWidth || 1280) - 3, r.right + 14),
137	        r.top + r.height / 2,
138	      );
139	      if (arrow && arrow !== nameEl) realClick(arrow);
140	      diag.push('策略1=店名+箭头');
141	    }
142	
143	    // 等下拉里出现「切换」
144	    let sw = await waitFor(function () {
145	      const cands = textEls(/^切换$/, 6).filter(visible);
146	      return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
147	    }, 2500, 200);
148	
149	    // 策略 2：读不到店名或没出「切换」→ 点右上角头像区
150	    if (!sw) {
151	      const av = [...document.querySelectorAll('img,div,span,button')].find((e) => {
152	        const r = e.getBoundingClientRect();
153	        return r.top >= 0 && r.top < 90
154	          && r.left > (window.innerWidth || 1280) * 0.82
155	          && r.width >= 18 && r.height >= 18
156	          && r.width <= 80 && r.height <= 80;
157	      });
158	      if (av) {
159	        realClick(av);
160	        diag.push('策略2=头像');
161	      } else {
162	        clickTopRightHotspot();
163	        diag.push('策略2=右上热区');
164	      }
165	      sw = await waitFor(function () {
166	        const cands = textEls(/^切换$/, 6).filter(visible);
167	        return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
168	      }, 3000, 200);
169	    }
170	
171	    diag.push('下拉切换=' + !!sw);
172	    if (sw) realClick(sw);
173	
174	    let ok = !!(await waitFor(function () { return modalOpen() ? true : null; }, 4500, 200));
175	
176	    // 策略 3：仍未开 → 再扫一次右上 + 放宽「切换」匹配（含「切换店铺」入口）
177	    if (!ok) {
178	      clickTopRightHotspot();
179	      await sleep(400);
180	      const loose = textEls(/^切换/, 12).filter(visible);
181	      diag.push('宽松切换候选=' + loose.length);
182	      if (loose.length) realClick(clickableAncestor(loose[loose.length - 1]));
183	      ok = !!(await waitFor(function () { return modalOpen() ? true : null; }, 4000, 200));
184	      diag.push('策略3=' + ok);
185	    }
186	
187	    if (!ok) {
188	      const cands = textEls(/切换/, 10).slice(0, 8).map((e) => {
189	        const b = e.getBoundingClientRect();
190	        return (e.tagName + '[' + (e.textContent || '').trim().slice(0, 8)
191	          + ',y' + Math.round(b.top) + ',v' + (visible(e) ? 1 : 0) + ']');
192	      });
193	      diag.push('切换候选=' + (cands.join(' ') || '无'));
194	      diag.push('模态 切换店铺=' + textEls(/切换店铺/, 20).length
195	        + ' 账户=' + textEls(/您的账户/, 40).length);
196	    }
197	    diag.push('弹窗打开=' + ok);
198	    return { ok: ok, diag: diag };
199	  }
200	`;
201	
202	/** 滚回顶部，避免顶栏店名因 scroll 出启发式范围 */
203	async function ensureTop(page) {
204	  await page.evaluate(() => {
205	    try {
206	      window.scrollTo(0, 0);
207	      document.documentElement.scrollTop = 0;
208	      document.body.scrollTop = 0;
209	    } catch {}
210	  }).catch(() => {});
211	  await page.waitForTimeout(200).catch(() => {});
212	}
213	
214	export async function readCurrentStoreName(page) {
215	  await ensureTop(page);
216	  return page.evaluate((helpers) => {
217	    // eslint-disable-next-line no-eval
218	    eval(helpers);
219	    return readStoreName();
220	  }, SWITCH_HELPERS);
221	}
222	
223	/**
224	 * 切换到目标店铺（会话级）。已是当前店则 ok。
225	 * @returns {Promise<{ok:boolean,msg:string}>}
226	 */
227	export async function switchSessionStore(page, target) {
228	  await ensureTop(page);
