239	          !isFakeStoreName(t) &&
240	          !/^(NEW|Beta|Seller|Central)$/i.test(t)
241	        );
242	      // 最短优先：避免拿到整行大段文本
243	      cands.sort((a, b) => a.length - b.length);
244	      if (cands.length) return cands[0];
245	      node = node.parentElement;
246	    }
247	    return null;
248	  }
249	  function closeModal() {
