338	  // 等弹窗里店铺行渲染完（标题先出、行后出，sleep 500 经常还是空的 → listStores=0）
339	  async function waitModalStoreRows() {
340	    return !!(await waitFor(() => {
341	      if (modalSwitchButtons().length > 0) return true;
342	      const tags = [...document.querySelectorAll('span,div,p')].filter((e) => {
343	        const t = (e.textContent || '').trim();
