// ---------- 切店自动化（轮巡用，由后台指令驱动） ----------
async function waitFor(fn, timeout, step) {
  const t0 = Date.now();
  for (;;) { let r; try { r = fn(); } catch (e) { r = null; } if (r) return r; if (Date.now() - t0 > (timeout || 6000)) return null; await sleep(step || 200); }
}
function textEls(re, maxLen) {
  return [...document.querySelectorAll('*')].filter((e) => { const t = (e.textContent || '').trim(); return re.test(t) && t.length <= (maxLen || 40); });
}
function innermost(els) { return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null; }
function clickableAncestor(el) { let n = el; for (let i = 0; i < 5 && n; i++) { if (n.tagName === 'BUTTON' || n.tagName === 'A' || n.getAttribute('role') === 'button') return n; n = n.parentElement; } return el; }
// 完整鼠标事件序列（很多组件要 mousedown/up 才触发，单纯 click 不生效）
function realClick(el) {
  if (!el) return false;
  const opts = { bubbles: true, cancelable: true, view: window };
  try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
  for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
    try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
  }
  try { el.click(); } catch (e) {}
  return true;
}
function modalOpen() { return textEls(/切换店铺|您的账户存在/, 20).length > 0; }
// 弹窗内可见的「切换」按钮（含当前店的禁用按钮）
function modalSwitchButtons() {
  return [...document.querySelectorAll('button,[role=button]')].filter((b) => {
    const t = (b.textContent || '').trim();
    return t === '切换' && visible(b);
  });
}
// 从切店弹窗一行里抠英文店名
function storeNameNear(el) {
  let node = el;
  for (let i = 0; i < 8 && node; i++) {
    const cands = [...node.querySelectorAll('span,div,p,a,button')]
      .map((e) => (e.textContent || '').trim())
      .filter((t) =>
        t.length >= 2 &&
        t.length <= 30 &&
        /^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t) &&
        !isFakeStoreName(t) &&
        !/^(NEW|Beta|Seller|Central)$/i.test(t)
      );
    // 最短优先：避免拿到整行大段文本
    cands.sort((a, b) => a.length - b.length);
    if (cands.length) return cands[0];
    node = node.parentElement;
  }
  return null;
}
function closeModal() {
  if (!modalOpen()) return true;
  const sels = [
    '[aria-label="Close"]',
    '[aria-label="关闭"]',
    '.beast-core-modal-close',
    '.semi-modal-close',
    '.SnowModal_closeIcon',
    '[class*="modal-close" i]',
    '[class*="Modal_close"]',
    '[class*="closeIcon" i]',
  ];
  for (const s of sels) {
    let x = null;
    try { x = document.querySelector(s); } catch (e) { /* 部分选择器含 i 标志旧引擎不支持 */ }
    if (x && visible(x)) { realClick(x); return true; }
  }
  // 标题「切换店铺」附近的圆形关闭按钮（截图标 X，常无文字）
  const title = innermost(textEls(/^切换店铺$/, 10).filter(visible));
  if (title) {
    let root = title;
    for (let i = 0; i < 8 && root; i++) {
      const closeCand = [...root.querySelectorAll('button,[role=button],span,i,div,svg')].find((el) => {
        if (!visible(el)) return false;
        const al = el.getAttribute('aria-label') || '';
        const cls = String(el.className || el.getAttribute('class') || '');
        if (/close|关闭/i.test(al) || /close/i.test(cls)) return true;
        const t = (el.textContent || '').trim();
        const r = el.getBoundingClientRect();
        // 空心/× 小按钮，偏右上
        if ((t === '' || t === '×' || t === '✕' || t === 'x' || t === 'X') && r.width > 8 && r.width < 48 && r.height > 8 && r.height < 48) {
          return r.top < 280 && r.left > window.innerWidth * 0.4;
        }
        return false;
      });
      if (closeCand) { realClick(closeCand); return true; }
      root = root.parentElement;
    }
  }
  // Escape 兜底（keydown + keyup，部分组件只听其一）
  for (const type of ['keydown', 'keyup']) {
    document.dispatchEvent(new KeyboardEvent(type, { key: 'Escape', code: 'Escape', keyCode: 27, which: 27, bubbles: true }));
  }
  return !modalOpen();
}

// 压缩输出某元素的 HTML 骨架（去 style/data 属性），便于回传诊断
function domSkel(el, maxLen) {
  if (!el) return 'null';
  let h = (el.outerHTML || '');
  h = h.replace(/\s(style|data-[\w-]+|aria-[\w-]+)="[^"]*"/g, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ');
  return h.slice(0, maxLen || 2200);
}

function visible(el) { const b = el.getBoundingClientRect(); return b.width > 0 && b.height > 0; }

async function openStoreModal(diag) {
  diag = diag || [];
  if (modalOpen()) { diag.push('弹窗已开'); return true; }
  const nameEl = findStoreNameEl();
  diag.push('店名=' + (nameEl ? (nameEl.textContent || '').trim() : 'null'));
  if (nameEl) {
    // 只点一次触发下拉：点店名的可点祖先 + 店名右侧箭头坐标（避免多次点击把下拉又关掉）
    const r = nameEl.getBoundingClientRect();
    realClick(clickableAncestor(nameEl));
    const el = document.elementFromPoint(Math.min(window.innerWidth - 3, r.right + 14), r.top + r.height / 2);
    if (el && el !== nameEl) realClick(el);
  }
  // 下拉里“切换”按钮：只认可见的、精确文本“切换”，取最后一个（下拉通常在 DOM 靠后）
  const sw = await waitFor(() => {
    const cands = textEls(/^切换$/, 6).filter(visible);
    return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
  }, 3500);
  diag.push('下拉切换按钮=' + !!sw);
  if (sw) realClick(sw);
  const ok = !!(await waitFor(() => (modalOpen() ? true : null), 4500));
  diag.push('弹窗打开=' + ok);
  if (!ok) {
    LOG.warn('Open store modal failed: ' + diag.join(' ; '));
    const cands = textEls(/切换/, 8).map((e) => {
      const b = e.getBoundingClientRect();
      return e.tagName + '.' + String(e.className || '').split(' ')[0] + '[' + (e.textContent || '').trim().slice(0, 6) + ',y' + Math.round(b.top) + ',w' + Math.round(b.width) + ']';
    });
    diag.push('切换候选(' + cands.length + ')=' + cands.join(' '));
    diag.push('模态计数 切换店铺=' + textEls(/切换店铺/, 20).length + ' 您的账户=' + textEls(/您的账户/, 40).length);
  }
  return ok;
}

// 等弹窗里店铺行渲染完（标题先出、行后出，sleep 500 经常还是空的 → listStores=0）
async function waitModalStoreRows() {
  return !!(await waitFor(() => {
    if (modalSwitchButtons().length > 0) return true;
    const tags = [...document.querySelectorAll('span,div,p')].filter((e) => {
      const t = (e.textContent || '').trim();
      return /^(半|全)?托管$/.test(t) && visible(e);
    });
    return tags.length ? true : null;
  }, 5000, 200));
}

async function listStores() {
  if (!(await openStoreModal())) return [];
  const rowsReady = await waitModalStoreRows();
  if (!rowsReady) LOG.warn('listStores: modal opened but store rows not ready');
  await sleep(300);
  // 以弹窗内每个「切换」按钮（含禁用的当前店）为一行，再抠英文店名。
  // 旧逻辑只认「可点的切换」→ 当前店被丢掉；且 /托管/ maxLen 过严时标签匹配不到 → 0 店。
  const names = [];
  const btns = modalSwitchButtons();
  for (const btn of btns) {
    const en = storeNameNear(btn);
    if (en) names.push(en);
  }
  // 兜底：半/全托管标签定位
  if (!names.length) {
    const tags = [...document.querySelectorAll('span,div,p')].filter((e) => {
      const t = (e.textContent || '').trim();
      return /^(半|全)?托管$/.test(t) && visible(e);
    });
    for (const tag of tags) {
      const en = storeNameNear(tag);
      if (en) names.push(en);
    }
  }
  // 务必关掉弹窗，避免卡在「切换店铺」遮罩上（旧 closeModal 选择器常点不到 X）
  closeModal();
  await sleep(200);
  if (modalOpen()) {
    closeModal();
    await sleep(200);
  }
  if (modalOpen()) LOG.warn('listStores: modal still open after close attempts');
  const uniq = [...new Set(names)];
  LOG.info('listStores: ' + uniq.length + ' stores: ' + uniq.join(', '));
  return uniq;
}

async function switchTo(target) {
  const diag = [];
  const cur = readStoreName();
  // 已是目标店：绝不要再点弹窗（当前店「切换」是灰的，旧逻辑会误点到别家或把弹窗留在页面上）
  if (cur && String(cur) === String(target)) {
    if (modalOpen()) closeModal();
    LOG.info('switchTo skip: already on ' + target);
    return { ok: true, msg: '已是当前店 ' + target + '，无需切换' };
  }
  if (!(await openStoreModal(diag))) return { ok: false, msg: '打不开弹窗 | ' + diag.join(' ; ') };
  await waitModalStoreRows();
  await sleep(200);
  const esc = String(target).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // 只在「切换」按钮附近的卡片里找店名，避免 textEls 命中整页大容器后误点别家
  let btn = null;
  for (const b of modalSwitchButtons()) {
    const name = storeNameNear(b);
    if (name && new RegExp('^' + esc + '$', 'i').test(name)) {
      // 禁用 = 已是当前店
      if (b.disabled || b.getAttribute('aria-disabled') === 'true') {
        closeModal();
        return { ok: true, msg: '弹窗显示已是当前店 ' + target };
      }
      btn = b;
      break;
    }
  }
  if (!btn) {
    // 兼容旧路径：按店名文本找行
    const rows = textEls(new RegExp(esc), 40).filter((e) => visible(e) && storeNameNear(e) && new RegExp('^' + esc + '$', 'i').test(storeNameNear(e) || ''));
    const row = innermost(rows);
    if (row) {
      btn = [...row.querySelectorAll('button,[role=button]')].find((b) => {
        const t = (b.textContent || '').trim();
        return t === '切换' && !b.disabled && b.getAttribute('aria-disabled') !== 'true';
      }) || null;
    }
  }
  if (!btn) {
    closeModal();
    return { ok: false, msg: '没找到可点的切换按钮(' + target + ')，可能已是当前店或不在列表' };
  }
  LOG.info('Switching store to: ' + target);
  realClick(btn); // 触发切店（SPA 更新或整页重载）
  // 若点击未真正切走，弹窗可能还在——稍等后强制关掉，避免遮罩卡死页面
  await sleep(1500);
  if (modalOpen()) {
    const now = readStoreName();
    if (now && String(now) === String(target)) {
      closeModal();
      return { ok: true, msg: '已在 ' + target + '（弹窗已关）' };
    }
    // 仍停在原店且弹窗在：点击可能没生效
    if (now && cur && String(now) === String(cur)) {
      closeModal();
      return { ok: false, msg: '已点切换但未离开 ' + cur + '，已关弹窗' };
    }
    // 店名暂时读不到（切店重载中）——不关，让页面自己走
  }
  return { ok: true, msg: '已点击切换到 ' + target };
}

// ---------- 主动捞「商品流量待关注」明细（发现异常时调，点筛选→扫→重置） ----------
// 读列表底部「共有 N 条」（筛选生效后该数=待关注总数）
function readTotalCount() {
  const el = [...document.querySelectorAll('*')].find(
    (x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || '')
  );
  if (!el) return null;
  const m = (el.textContent || '').match(/共有\s*([\d,]+)\s*条/);
  return m ? Number(m[1].replace(/,/g, '')) : null;
}
// 定位「商品流量待关注」快速筛选 chip 容器（与 readChipCount 同一稳定 class 前缀）
function findWatchChip() {
  for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
    if (/商品流量待关注/.test(card.textContent || '')) return card;
  }
  return null;
}
// 点「重置」清掉快速筛选，恢复用户视图
function clickReset() {
  const btn = textEls(/^重置$/, 6).filter(visible)[0];
  if (btn) realClick(clickableAncestor(btn));
}
// 点开「商品流量待关注」筛选 → 扫出这几条商品(productId+name+skc) → 重置。
// 筛选生效后网格里每行都是待关注商品，故取全部行（不再依赖行内徽标）。
// 只覆盖筛选后的当前页(默认 20 条)，>20 条的溢出由 total 提示行说明。
async function scanWatchList() {
  LOG.info('scanWatchList: scanning...');
  const chip = findWatchChip();
  if (!chip) { LOG.warn('scanWatchList: chip not found'); return { store: readStoreName(), items: [], applied: false, msg: '未找到待关注筛选 chip' }; }
  const before = readTotalCount();
  realClick(clickableAncestor(chip));

