  }
  // 在弹窗内枚举店名：叶子英文 + 同行有「切换」或「托管/当前店铺」
  function listStoreNamesInModal(root) {
    if (!root) return [];
    const names = [];
    const leaves = root.querySelectorAll('span,div,p,a,b,strong,label');
    for (const el of leaves) {
      if (!visible(el)) continue;
      if (el.children.length > 0) {
        // 允许 elli_outerWrapper 这种单文本子结构：若子全是非元素文本容器也可
        const onlyText = [...el.childNodes].every((n) => n.nodeType === 3 || (n.nodeType === 1 && !(n.textContent || '').trim()));
        if (!onlyText && el.children.length > 0) {
          // 若唯一子是文本叶子，仍可取
          if (!(el.children.length === 1 && el.children[0].children.length === 0)) continue;
        }
      }
      const t = (el.textContent || '').trim();
      if (!isStoreNameText(t)) continue;
      let card = el.parentElement;
      let near = false;
      for (let i = 0; i < 8 && card && card !== root.parentElement; i++) {
        const ct = card.textContent || '';
        if (/切换/.test(ct) && (/托管|当前店铺|全托管|半托管/.test(ct))) { near = true; break; }
        // 行高有限的卡片
        const r = card.getBoundingClientRect();
        if (r.height > 40 && r.height < 160 && /切换/.test(ct) && isStoreNameText(t)) { near = true; break; }
        card = card.parentElement;
      }
      if (near) names.push(t);
    }
    // 再按「切换」控件回溯
    for (const sw of modalSwitchControls(root)) {
      const n = storeNameNear(sw);
      if (n) names.push(n);
    }
    return [...new Set(names)];
  }
  function closeModal() {
    if (!modalOpen()) return true;
    const root = findModalRoot();
    const sels = [
      '[aria-label="Close"]',
      '[aria-label="close"]',
      '[aria-label="关闭"]',
      '.beast-core-modal-close',
      '.semi-modal-close',
      '.SnowModal_closeIcon',
      '[class*="modal-close"]',
      '[class*="Modal_close"]',
      '[class*="closeIcon"]',
      '[class*="CloseIcon"]',
      '[class*="close-icon"]',
      '[data-testid*="close"]',
    ];
    const scopes = root ? [root, document] : [document];
    for (const scope of scopes) {
      for (const s of sels) {
        let nodes = [];
        try { nodes = [...scope.querySelectorAll(s)]; } catch (e) { continue; }
        for (const x of nodes) {
          if (x && visible(x)) {
            realClick(x);
            if (!modalOpen()) return true;
          }
        }
      }
    }
    // 坐标点弹窗右上角 X（截图里是圆形关闭，常无文字/无 close class）
    if (root) {
      const r = root.getBoundingClientRect();
      const points = [
        [r.right - 18, r.top + 18],
        [r.right - 28, r.top + 28],
        [r.right - 22, r.top + 22],
        [r.right - 36, r.top + 20],
        [r.right - 14, r.top + 32],
        [r.right - 44, r.top + 24],
      ];
      for (const [x, y] of points) {
        const el = document.elementFromPoint(x, y);
        if (!el) continue;
        // 不要点到标题文字本身
        if (/切换店铺|您的账户/.test((el.textContent || '').trim()) && (el.textContent || '').trim().length > 2) continue;
        realClick(clickableAncestor(el));
        if (!modalOpen()) return true;
      }
    }
    // 点遮罩
    const masks = document.querySelectorAll('[class*="modal-mask"],[class*="Modal_mask"],[class*="mask"],[class*="Mask"]');
    for (const m of masks) {
