// 在弹窗内枚举店名。优先 innerText 按行解析（不依赖 button/叶子结构，最稳）
  function listStoreNamesInModal(root) {
    if (!root) return [];
    const names = [];
    // ① 按可见文本行解析（截图结构：店名 / 半托管 / 切换 常各占一行）
    try {
      const raw = String(root.innerText || root.textContent || '');
      for (const line of raw.split(/\r?\n/)) {
        const t = line.replace(/\s+/g, ' ').trim();
        if (!t) continue;
        if (isStoreNameText(t)) { names.push(t); continue; }
        // "HomeCove 半托管" / "Twilight Cove 半托管 切换"
        const m = t.match(/^([A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,4})(?:\s+(?:半托管|全托管|当前店铺|切换).*)?$/);
        if (m && isStoreNameText(m[1])) names.push(m[1]);
      }
    } catch (e) {}
    // ② DOM 叶子 + 卡片上下文
    if (!names.length) {
      const leaves = root.querySelectorAll('span,div,p,a,b,strong,label');
      for (const el of leaves) {
        if (!visible(el)) continue;
        if (el.children.length > 1) continue;
        const t = (el.textContent || '').trim();
        if (!isStoreNameText(t)) continue;
        let card = el.parentElement;
        let near = false;
        for (let i = 0; i < 8 && card && card !== root.parentElement; i++) {
          const ct = card.textContent || '';
          if (/切换/.test(ct) && (/托管|当前店铺|全托管|半托管/.test(ct))) { near = true; break; }
          const r = card.getBoundingClientRect();
          if (r.height > 40 && r.height < 160 && /切换/.test(ct)) { near = true; break; }
          card = card.parentElement;
        }
        if (near) names.push(t);
      }
    }
    // ③ 「切换」控件回溯
    for (const sw of modalSwitchControls(root)) {
      const n = storeNameNear(sw);
      if (n) names.push(n);
    }
    return [...new Set(names)];
  }

