      const listed = await sendTabRetry(tab.id, { cmd: 'listStores' }, 5);
      listedNames = (listed && listed.names) || [];
    }
    const names = [...new Set([...known, ...listedNames])].filter(Boolean);
    cycleLog.push(
      known.length >= 2
        ? ('店铺(已知)：' + names.join(', '))
        : ('店铺(已知' + known.length + '+探测' + listedNames.length + ')：' + names.join(', '))
    );
