// 从切店弹窗一行里抠英文店名
  function storeNameNear(el) {
    let node = el;
    for (let i = 0; i < 10 && node; i++) {
      const cands = [];
      for (const e of node.querySelectorAll('span,div,p,a,button,b,strong,label')) {
        if (e.children.length > 1) continue;
        const t = (e.textContent || '').trim();
        if (isStoreNameText(t)) cands.push(t);
      }
      // 节点自身
      const self = (node.textContent || '').trim();
      if (isStoreNameText(self)) cands.push(self);
      cands.sort((a, b) => a.length - b.length);
      if (cands.length) return cands[0];
      node = node.parentElement;
    }
    return null;
  }
  // 在弹窗内枚举店名。优先 innerText 按行解析（不依赖 button/叶子结构，最稳）
  function listStoreNamesInModal(root) {
    if (!root) return [];
    const names = [];
    // ① 按可见文本行解析（截图结构：店名 / 半托管 / 切换 常各占一行）
    try {
      const raw = String(root.innerText || root.textContent || '');
      for (const line of raw.split(/\r?\n/)) {
        const t = line.replace(/\s+/g, ' ').trim();
        if (!t) continue;
        if (isStoreNameText(t)) { names.push(t); continue; }
        // "HomeCove 半托管" / "Twilight Cove 半托管 切换"
        const m = t.match(/^([A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,4})(?:\s+(?:半托管|全托管|当前店铺|切换).*)?$/);
        if (m && isStoreNameText(m[1])) names.push(m[1]);
      }
    } catch (e) {}
    // ② DOM 叶子 + 卡片上下文
    if (!names.length) {
      const leaves = root.querySelectorAll('span,div,p,a,b,strong,label');
      for (const el of leaves) {
        if (!visible(el)) continue;
        if (el.children.length > 1) continue;
        const t = (el.textContent || '').trim();
        if (!isStoreNameText(t)) continue;
        let card = el.parentElement;
        let near = false;
        for (let i = 0; i < 8 && card && card !== root.parentElement; i++) {
          const ct = card.textContent || '';
          if (/切换/.test(ct) && (/托管|当前店铺|全托管|半托管/.test(ct))) { near = true; break; }
          const r = card.getBoundingClientRect();
          if (r.height > 40 && r.height < 160 && /切换/.test(ct)) { near = true; break; }
          card = card.parentElement;
        }
        if (near) names.push(t);
      }
    }
    // ③ 「切换」控件回溯
    for (const sw of modalSwitchControls(root)) {
      const n = storeNameNear(sw);
      if (n) names.push(n);
    }
    return [...new Set(names)];
  }

input.new_string:
// 从切店弹窗一行里抠英文店名
  function storeNameNear(el) {
    let node = el;
    for (let i = 0; i < 10 && node; i++) {
      const cands = [];
      // 直接文本节点（HomeCove 常是 mallName 下的裸文本，不在单独 span 里）
      for (const child of node.childNodes) {
        if (child.nodeType === 3) {
          const n = extractStoreName(child.textContent || '');
          if (n) cands.push(n);
        }
      }
      for (const e of node.querySelectorAll('span,div,p,a,button,b,strong,label')) {
        const n = extractStoreName((e.textContent || '').trim());
        if (n) cands.push(n);
        for (const child of e.childNodes) {
          if (child.nodeType === 3) {
            const n2 = extractStoreName(child.textContent || '');
            if (n2) cands.push(n2);
          }
        }
      }
      const self = extractStoreName((node.textContent || '').trim());
      if (self) cands.push(self);
      // 优先较短的纯店名
      cands.sort((a, b) => a.length - b.length);
      if (cands.length) return cands[0];
      node = node.parentElement;
    }
    return null;
  }
  // 在弹窗内枚举店名
  function listStoreNamesInModal(root) {
    if (!root) return [];
    const names = [];
    // ① 最稳：class 含 mallName（真实结构 account-info_mallName__xxx）
    for (const el of root.querySelectorAll('[class*="mallName"],[class*="mallInfo"],[class*="MallName"]')) {
      // 优先第一个文本节点 = 纯店名
      for (const child of el.childNodes) {
        if (child.nodeType === 3) {
          const n = extractStoreName(child.textContent || '');
          if (n) { names.push(n); break; }
        }
      }
      const n2 = extractStoreName((el.textContent || '').trim());
      if (n2) names.push(n2);
    }
    // ② innerText / textContent 整段（"HomeCove半托管 切换 Twilight Cove半托管…"）
    try {
      const raw = String(root.innerText || root.textContent || '');
      // 全局扫：英文店名紧贴可选的半托管/切换
      const re = /([A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,4})(?=半托管|全托管|当前店铺|\s*切换|$|\n)/g;
      let m;
      while ((m = re.exec(raw))) {
        const n = extractStoreName(m[1]);
        if (n) names.push(n);
      }
      for (const line of raw.split(/\r?\n/)) {
        const n = extractStoreName(line);
        if (n) names.push(n);
      }
    } catch (e) {}
    // ③ 「切换」按钮向上回溯
    for (const sw of modalSwitchControls(root)) {
      const n = storeNameNear(sw);
      if (n) names.push(n);
    }
    // ④ 卡片 section
    for (const sec of root.querySelectorAll('[class*="mallSection"],[class*="switchSection"]')) {
      const n = extractStoreName((sec.textContent || '').trim());
      if (n) names.push(n);
      for (const child of sec.childNodes) {
        if (child.nodeType === 3) {
          const n2 = extractStoreName(child.textContent || '');
          if (n2) names.push(n2);
        }
      }
    }
    return [...new Set(names)].filter((n) => n && !isFakeStoreName(n));
  }

